parameters.jsCode:
return [
  {
    json: {
      event_type: "SAFETY_VIOLATION",
      event_code: "SAFE_001",
      workflow_stage: "INGESTION",
      success: false,
      severity: "CRITICAL",
      claim_status: "BLOCKED_UNSAFE_CONTENT",
      message: "Unsafe image content detected.",
      moderation_reason: $json.reason || "Policy violation detected.",
      details: {
        severity_scores: $json.severity_scores || {}
      },
      timestamp: new Date().toISOString()
    }
  }
];

return {
  json: {

    internal_claim_id: $json.internal_claim_id,

    claim_id: $json.claim_id,

    workflow_stage: $json.workflow_stage,

    event_type: $json.event_type,

    severity: $json.severity,

    message: $json.message,

    event_status: $json.success ? 'SUCCESS' : 'FAILED',

    metadata: {
      source_field: $json.source_field,
      file_name: $json.file_name,
      mime_type: $json.mime_type,
      storage_key: $json.storage_key
    },

    created_at: new Date().toISOString()

  }
};

parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "image_safe",
    "image_relevant",
    "contains_vehicle",
    "damage_visible",
    "evidence_quality",
    "fraud_suspicion",
    "human_review_required",
    "decision"
  ],
  "properties": {
    "image_safe": {
      "type": "boolean",
      "description": "Whether the image is safe and appropriate."
    },

    "image_relevant": {
      "type": "boolean",
      "description": "Whether the image is relevant to the insurance claim."
    },

    "contains_vehicle": {
      "type": "boolean",
      "description": "Whether a vehicle is visibly present."
    },

    "damage_visible": {
      "type": "boolean",
      "description": "Whether visible vehicle damage exists."
    },

    "evidence_quality": {
      "type": "string",
      "enum": [
        "HIGH",
        "MEDIUM",
        "LOW"
      ],
      "description": "Overall image evidence quality."
    },

    "fraud_suspicion": {
      "type": "string",
      "enum": [
        "LOW",
        "MEDIUM",
        "HIGH"
      ],
      "description": "Fraud suspicion assessment level."
    },

    "human_review_required": {
      "type": "boolean",
      "description": "Whether manual review is required."
    },

    "decision": {
      "type": "string",
      "enum": [
        "APPROVED",
        "HUMAN_REVIEW",
        "REJECTED"
      ],
      "description": "Final insurance image processing decision."
    }
  }
}
